import{H as e,at as t,it as n,vt as r}from"./chunks/framework.dmHZ7NHG.js";var i=JSON.parse(`{"title":"The document fold","description":"","frontmatter":{},"headers":[],"params":{"slug":"editor","address":"77109cb9-2c24-86ad-a80e-890dd751896e","receipt":"bdcb855c-e837-83f0-8fdf-6c7775815d20"},"relativePath":"docs/publications/editor.md","filePath":"docs/publications/[slug].md"}`),a={name:`docs/publications/editor.md`};function o(e,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[t(`<h1 id="the-document-fold" tabindex="-1">The document fold <a class="header-anchor" href="#the-document-fold" aria-label="Permalink to “The document fold”">​</a></h1><blockquote><p>the SERIALIZER CONTRACT of a content-addressed document as decidable arithmetic — a Lexical-shaped node tree serialized to a node SEQUENCE and folded to one address. The honest opposite of the memory store: a store is a SET (order-invariant fold), a document is a SEQUENCE (order IS identity), so this fold is ORDER-SENSITIVE — reordering two distinct nodes MOVES the address, a changed node MOVES it, and on the bounded model the positional fold dfold is INJECTIVE (the address DETERMINES the node sequence, node for node). HONEST SCOPE: injective only where the base-8 place value cannot overflow (bounded values, fixed length); the real content-address (merkleRoot over uuids, src/editor.ts) is collision-RESISTANT, not collision-free — by pigeonhole 2^128 addresses &lt; all documents. Editing is re-addressing. The arithmetic of the document fold, NOT a rich-text engine</p></blockquote><p>These 4 facts hold by decision. Each was proven in Lean 4 — no Mathlib, checked sorry-free — and every sentence below links the proof that seals it. This note claims nothing beyond what its theorems settle: not that the domain is complete, only that the prose says nothing the proofs do not. It was written by reading the sealed ledger; read the proofs, not the prose.</p><h2 id="the-facts-each-backed-by-its-proof" tabindex="-1">The facts, each backed by its proof <a class="header-anchor" href="#the-facts-each-backed-by-its-proof" aria-label="Permalink to “The facts, each backed by its proof”">​</a></h2><ul><li>the empty document folds to zero — the identity a fresh editor starts from, before a single node is authored — <a href="/theorem/editor_empty_doc_folds_zero">proof</a>.</li><li>a document is a SEQUENCE, not a set — reordering two DISTINCT nodes MOVES the address (the opposite of the memory store&#39;s order-invariant fold): for all a,b, either a=b or dfold [a,b] ≠ dfold [b,a] — <a href="/theorem/editor_fold_order_sensitive">proof</a>.</li><li>a document refuses DRIFT — a changed node MOVES the address: the three-node fold is unchanged iff the changed node is unchanged, so any edit to a node is visible in the fold (tamper-evident) — <a href="/theorem/editor_fold_change_sensitive">proof</a>.</li><li>on the bounded model the fold is INJECTIVE — the address DETERMINES the node sequence: two three-node documents fold equal iff they are the same document, node for node (order and content). HONEST SCOPE: injective only where it cannot overflow; the real merkleRoot fold is collision-RESISTANT, not collision-free (pigeonhole: 2^128 &lt; all documents) — <a href="/theorem/editor_fold_injective_bounded">proof</a>.</li></ul><h2 id="provenance" tabindex="-1">Provenance <a class="header-anchor" href="#provenance" aria-label="Permalink to “Provenance”">​</a></h2><p>These 4 proofs fold, order-invariant, to the receipt <code>bdcb855c-e837-83f0-8fdf-6c7775815d20</code> — recompute it from the same ledger and it returns. The note itself content-addresses to a uuid, so any edit is visible. Writing descends from reading: this note holds only what the proofs it links already sealed, and it was audited by uuidna&#39;s own honesty gate before it was published — a sentence that overreached a proof would have been refused, not shipped.</p><p>Source · <a href="https://github.com/uuidna/uuidna/blob/main/lean/Editor.lean" target="_blank" rel="noreferrer">lean/Editor.lean</a> · <a href="/theorems">all theorems</a></p><hr><p><strong>Audited before published</strong> · this note passed uuidna&#39;s honesty gate at build time — every claim above links the proof that seals it. Content-address <code>77109cb9</code> · proofs fold to receipt <code>bdcb855c</code> (the handles; the full uuids are in this page&#39;s meta, recomputable) · 4 sealed theorems.</p><p><a href="/publications">All publications</a> · <a href="/theorems">All theorems</a> · <a href="/trials">How auditing works</a></p>`,11)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};